/**
 * Compile-time contract between the backend (Pydantic response models →
 * src/api-schema.d.ts, regenerated by `npm run gen:api`) and the types the UI
 * uses. If the server changes a response shape, `tsc` fails here.
 */
import type { components } from './api-schema';
import type {
  Admin,
  Booking,
  ChatMessage,
  ChatThread,
  Config,
  Mentor,
  Notice,
  Progress,
  Quiz,
  Slot,
  Subject,
  User,
  Waitlist,
} from './types';

type S = components['schemas'];
type Assignable<From extends To, To> = [From, To];

export type ApiContract = [
  Assignable<S['UserOut'], User>,
  Assignable<S['SubjectOut'], Subject>,
  Assignable<S['MentorCardOut'], Mentor>,
  Assignable<S['MySlotOut'], Slot>,
  Assignable<S['BookingOut'], Booking>,
  Assignable<S['LessonOut'], Booking>,
  Assignable<S['ProgressOut'], Progress>,
  Assignable<S['NotificationOut'], Notice>,
  Assignable<S['WaitlistOut'], Waitlist>,
  Assignable<S['ConfigOut'], Config>,
  Assignable<S['QuizOut'], Quiz>,
  Assignable<S['AdminOut'], Admin>,
  Assignable<S['MessageOut'], ChatMessage>,
  Assignable<S['ThreadOut'], ChatThread>,
];
